+class ContactForm {
+  constructor() {
+    this.form = document.getElementById('contactForm');
+    this.fullNameInput = document.getElementById('fullName');
+    this.emailInput = document.getElementById('email');
+    this.phoneInput = document.getElementById('phone');
+    this.successMessage = document.getElementById('successMessage');
+
+    this.setupEventListeners();
+  }
+
+  setupEventListeners() {
+    this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+
+    this.fullNameInput.addEventListener('blur', () => this.validateFullName());
+    this.emailInput.addEventListener('blur', () => this.validateEmail());
+    this.phoneInput.addEventListener('blur', () => this.validatePhone());
+
+    this.fullNameInput.addEventListener('input', () => this.clearError('fullName'));
+    this.emailInput.addEventListener('input', () => this.clearError('email'));
+    this.phoneInput.addEventListener('input', () => this.clearError('phone'));
+  }
+
+  validateFullName() {
+    const value = this.fullNameInput.value.trim();
+    const errorElement = document.getElementById('fullNameError');
+
+    if (!value) {
+      this.setError('fullName', 'Full name is required');
+      return false;
+    }
+
+    if (value.length < 2) {
+      this.setError('fullName', 'Full name must be at least 2 characters');
+      return false;
+    }
+
+    this.clearError('fullName');
+    return true;
+  }
+
+  validateEmail() {
+    const value = this.emailInput.value.trim();
+    const errorElement = document.getElementById('emailError');
+    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+    if (!value) {
+      this.setError('email', 'Email address is required');
+      return false;
+    }
+
+    if (!emailRegex.test(value)) {
+      this.setError('email', 'Please enter a valid email address');
+      return false;
+    }
+
+    this.clearError('email');
+    return true;
+  }
+
+  validatePhone() {
+    const value = this.phoneInput.value.trim();
+    const errorElement = document.getElementById('phoneError');
+
+    if (!value) {
+      this.clearError('phone');
+      return true;
+    }
+
+    const phoneRegex = /^(\+?1[-.\s]?)?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}$/;
+
+    if (!phoneRegex.test(value)) {
+      this.setError('phone', 'Please enter a valid phone number');
+      this.phoneInput.classList.remove('valid-phone');
+      return false;
+    }
+
+    this.clearError('phone');
+    this.phoneInput.classList.add('valid-phone');
+    return true;
+  }
+
+  setError(fieldName, message) {
+    const errorElement = document.getElementById(`${fieldName}Error`);
+    if (errorElement) {
+      errorElement.textContent = message;
+    }
+  }
+
+  clearError(fieldName) {
+    const errorElement = document.getElementById(`${fieldName}Error`);
+    if (errorElement) {
+      errorElement.textContent = '';
+    }
+  }
+
+  handleSubmit(e) {
+    e.preventDefault();
+
+    const isFullNameValid = this.validateFullName();
+    const isEmailValid = this.validateEmail();
+    const isPhoneValid = this.validatePhone();
+
+    if (isFullNameValid && isEmailValid && isPhoneValid) {
+      this.submitForm();
+    }
+  }
+
+  submitForm() {
+    const formData = {
+      fullName: this.fullNameInput.value.trim(),
+      email: this.emailInput.value.trim(),
+      phone: this.phoneInput.value.trim(),
+    };
+
+    console.log('Form submitted:', formData);
+
+    this.form.reset();
+    this.clearError('fullName');
+    this.clearError('email');
+    this.clearError('phone');
+    this.phoneInput.classList.remove('valid-phone');
+
+    this.successMessage.setAttribute('aria-hidden', 'false');
+    setTimeout(() => {
+      this.successMessage.setAttribute('aria-hidden', 'true');
+    }, 5000);
+  }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+  new ContactForm();
+});
+
